<script setup lang="ts">import{onMounted,ref}from'vue';import QRCode from'qrcode';const registrationUrl=`${window.location.origin}/visitor/register`,qrData=ref('');onMounted(async()=>qrData.value=await QRCode.toDataURL(registrationUrl,{width:360,margin:2,color:{dark:'#123c33',light:'#ffffff'}}));function download(){const a=document.createElement('a');a.href=qrData.value;a.download='万盛股份访客登记二维码.png';a.click()}function printPage(){window.print()}</script>
<template><div class="qr-page"><section class="panel qr-card"><div class="brand qr-brand"><span class="brand-mark">万</span><div><h1>万盛股份</h1><p>访客扫码登记</p></div></div><img v-if="qrData" :src="qrData" alt="访客登记二维码"/><h2>微信扫码填写来访申请</h2><p class="muted">二维码自动指向当前系统的访客登记入口</p><code>{{registrationUrl}}</code><div class="qr-actions"><button @click="download">下载二维码</button><button class="secondary-button" @click="printPage">打印</button></div></section></div></template>
